-- ============================================================================
-- 553_ownership_start_dates_county.sql  (Ed 2026-10-31)
-- ----------------------------------------------------------------------------
-- Replaces roster-load dates that were recorded as ownership start dates.
--
-- WHY: when each Fort Bend roster was loaded, the load date was written as every
-- owner's start date (Quail Ridge 5/18, Waterview 5/19 + 5/26, Still Creek 5/21,
-- Canyon Gate 5/26/2026). Those dates are false: they say each owner took title
-- the day we loaded the roster. The transfer path (approve_ownership_proposal)
-- then refuses any real sale that settled before that date, e.g. the pending
-- Waterview transfer proposal 0f146aca (settlement 2026-05-04, seller recorded
-- as starting 2026-05-19).
--
-- WHAT (2,332 current ownership periods, listed below by id; nothing else):
--   * 1,216 get the county deed date as their start, where the Fort Bend CAD
--     roll matches the lot to exactly one parcel, the county owner name agrees
--     with ours, the deed date is before the roster load and after any prior
--     owner period we hold, and Vantaca's account history does not contradict
--     it. start_date_basis = 'county_deed': recording evidence from the county
--     appraisal roll, NOT a confirmed closing date.
--   * 1,116 have no reliable county date and become NULL, the schema's
--     "before trustEd history" (start_date_basis = 'unknown').
--   * Every change is recorded in ownership_start_date_corrections with the
--     prior date, the reason and the county evidence (roll, file + sha256,
--     retrieval date, CAD reference, property number, instrument, deed date).
--   * property_ownerships.start_date becomes nullable (the tenure table already
--     is) and each listed period's open ownership rows get the same start.
--
-- NOT CHANGED: owners, contacts, accounts, end dates, balances, ledger, GL,
-- proposals, home sales; every start date that came from an approved transfer
-- or any other date not listed here; Lakes of Pine Forest (Harris County, no
-- county evidence loaded yet), Eaglewood (archived), August Meadows (already
-- NULL), the demo community. County records never change who owns a lot: owner
-- differences go to staff review, never into this migration.
--
-- The list is fixed (generated 2026-10-31 from the 2026 certified FBCAD roll and
-- the 2026 preliminary roll, read-only). It carries ids, dates and public county
-- parcel/instrument numbers only. If any listed period no longer has the
-- expected roster-load start, or any open ownership on it was changed, the
-- migration refuses and changes nothing.
--
-- Guards: identity of every tenure and ownership row, every balance view, every
-- property account number and every untouched start date is fingerprinted
-- before and after; any difference rolls everything back.
-- Record ownership: association_record (ownership roster and its audit trail).
-- ============================================================================
BEGIN;

ALTER TABLE property_ownerships ALTER COLUMN start_date DROP NOT NULL;
COMMENT ON COLUMN property_ownerships.start_date IS
  'When this owner took title, when known. NULL = not known (before trustEd history). Never the date a roster or import was loaded.';

ALTER TABLE ownership_tenures ADD COLUMN IF NOT EXISTS start_date_basis text;
DO $c$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ownership_tenures_start_date_basis_check') THEN
    ALTER TABLE ownership_tenures ADD CONSTRAINT ownership_tenures_start_date_basis_check
      CHECK (start_date_basis IS NULL OR start_date_basis IN ('settlement', 'county_deed', 'unknown'));
  END IF;
END $c$;
COMMENT ON COLUMN ownership_tenures.start_date_basis IS
  'What start_date is: settlement (an approved transfer), county_deed (the county appraisal roll''s deed date for this owner: recording evidence, not a confirmed closing date), unknown (start_date NULL). NULL = not classified.';

CREATE TABLE IF NOT EXISTS ownership_start_date_corrections (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  community_id         uuid NOT NULL REFERENCES communities(id) ON DELETE RESTRICT,
  property_id          uuid NOT NULL REFERENCES properties(id) ON DELETE RESTRICT,
  tenure_id            uuid NOT NULL REFERENCES ownership_tenures(id) ON DELETE RESTRICT,
  ownership_ids        uuid[] NOT NULL,
  prior_start_date     date NOT NULL,
  corrected_start_date date,
  action               text NOT NULL CHECK (action IN ('county_deed_date', 'cleared_unknown')),
  reason               text NOT NULL CHECK (reason IN ('county_deed_date', 'no_county_parcel', 'multiple_county_parcels', 'owner_name_differs',
                         'no_county_deed_date', 'county_files_disagree', 'deed_after_roster_load', 'placeholder_prior_tenure',
                         'deed_before_prior_owner_end', 'deed_predates_vantaca_account')),
  evidence             jsonb NOT NULL,
  migration            text NOT NULL DEFAULT '553_ownership_start_dates_county.sql',
  created_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT ownership_start_date_corrections_one_per_tenure UNIQUE (tenure_id),
  CONSTRAINT ownership_start_date_corrections_shape CHECK ((action = 'county_deed_date') = (corrected_start_date IS NOT NULL)
    AND (action = 'county_deed_date') = (reason = 'county_deed_date') AND (corrected_start_date IS NULL OR corrected_start_date < prior_start_date))
);
CREATE INDEX IF NOT EXISTS idx_ownership_start_date_corrections_property ON ownership_start_date_corrections (property_id);
CREATE INDEX IF NOT EXISTS idx_ownership_start_date_corrections_community ON ownership_start_date_corrections (community_id);
COMMENT ON TABLE ownership_start_date_corrections IS
  'Permanent record of each ownership start date replaced by migration 553 (roster-load dates): the prior date, the corrected date or NULL, why, and the county evidence. Append-only.';

CREATE OR REPLACE FUNCTION ownership_start_date_corrections_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  RAISE EXCEPTION 'ownership start-date corrections are a permanent record (no %)', lower(TG_OP) USING ERRCODE = 'check_violation';
END;
$fn$;
DROP TRIGGER IF EXISTS trg_ownership_start_date_corrections_guard ON ownership_start_date_corrections;
CREATE TRIGGER trg_ownership_start_date_corrections_guard BEFORE UPDATE OR DELETE ON ownership_start_date_corrections
  FOR EACH ROW EXECUTE FUNCTION ownership_start_date_corrections_guard();
GRANT SELECT ON ownership_start_date_corrections TO service_role;

CREATE TEMP TABLE _m553 (
  tenure_id uuid PRIMARY KEY, property_id uuid NOT NULL, community_id uuid NOT NULL, prior_start date NOT NULL, new_start date,
  reason text NOT NULL, roll text, cad_reference text, property_number text, instrument text, deed_date date
) ON COMMIT DROP;

DO $m553$
DECLARE
  n bigint; v bigint; h text; todo bigint;
  verified constant text[] := ARRAY['ownership_proposal_approval', 'vantaca_transfer_report', 'title_transfer'];
  b_bal text; b_cur text; b_former text; b_props text; b_ten text; b_own text; b_ten_other text; b_own_other text;
BEGIN
  SELECT count(*) INTO n FROM _m553;
  IF n <> 2332 THEN RAISE EXCEPTION 'precondition: the list has % rows, expected 2332', n; END IF;
  SELECT count(*) INTO n FROM _m553 WHERE (new_start IS NULL) <> (reason <> 'county_deed_date');
  IF n <> 0 THEN RAISE EXCEPTION 'precondition: % list rows mix a date with a clearing reason', n; END IF;
  SELECT count(*) INTO n FROM _m553 WHERE new_start IS NOT NULL
     AND (new_start >= prior_start OR new_start < DATE '1900-01-01' OR deed_date IS DISTINCT FROM new_start OR roll IS NULL OR cad_reference IS NULL);
  IF n <> 0 THEN RAISE EXCEPTION 'precondition: % county dates lack evidence or are not before the roster load', n; END IF;

  -- Re-run: periods already corrected are skipped; nothing else is touched.
  DELETE FROM _m553 d USING ownership_start_date_corrections c WHERE c.tenure_id = d.tenure_id;
  SELECT count(*) INTO todo FROM _m553;
  IF todo = 0 THEN RAISE NOTICE 'mig 553: every listed period was already corrected; nothing to do'; RETURN; END IF;
  IF todo <> 2332 THEN RAISE EXCEPTION 'precondition: % of 2332 listed periods were already corrected; a partial state needs review', 2332 - todo; END IF;

  -- Each listed period is still exactly what the reconciliation saw.
  SELECT count(*) INTO n FROM _m553 d LEFT JOIN ownership_tenures t ON t.id = d.tenure_id
   WHERE t.id IS NULL OR t.property_id IS DISTINCT FROM d.property_id OR t.community_id <> d.community_id OR t.kind <> 'owner'
      OR t.origin <> 'backfill_current' OR t.end_date IS NOT NULL OR t.created_by_proposal_id IS NOT NULL
      OR t.start_date IS DISTINCT FROM d.prior_start OR t.start_date_basis IS NOT NULL;
  IF n <> 0 THEN RAISE EXCEPTION 'precondition: % listed ownership periods changed since the reconciliation; regenerate the list', n; END IF;
  SELECT count(*) INTO n FROM property_ownerships o JOIN _m553 d ON d.tenure_id = o.tenure_id
   WHERE o.end_date IS NULL AND (o.start_date IS DISTINCT FROM d.prior_start OR o.source = ANY (verified) OR o.property_id <> d.property_id);
  IF n <> 0 THEN RAISE EXCEPTION 'precondition: % open ownerships on listed periods carry a different or verified start', n; END IF;
  SELECT count(*) INTO n FROM _m553 d WHERE NOT EXISTS (SELECT 1 FROM property_ownerships o WHERE o.tenure_id = d.tenure_id AND o.end_date IS NULL);
  IF n <> 0 THEN RAISE EXCEPTION 'precondition: % listed periods have no open ownership', n; END IF;
  -- A county date never reaches back over an owner period we already hold.
  SELECT count(*) INTO n FROM _m553 d JOIN ownership_tenures p ON p.property_id = d.property_id AND p.id <> d.tenure_id
   WHERE d.new_start IS NOT NULL AND (p.end_date IS NULL OR p.end_date >= d.new_start);
  IF n <> 0 THEN RAISE EXCEPTION 'precondition: % county dates overlap another owner period on the lot', n; END IF;

  -- BEFORE fingerprints.
  SELECT md5(coalesce(string_agg(community_id::text || '|' || coalesce(vantaca_account_id, '') || '|' || coalesce(property_id::text, '') || '|' || coalesce(contact_id::text, '') || '|' || balance_cents::text, ',' ORDER BY community_id, vantaca_account_id, property_id, contact_id), '')) INTO b_bal FROM v_homeowner_current_balance;
  SELECT md5(coalesce(string_agg(community_id::text || '|' || property_id::text || '|' || tenure_id::text || '|' || balance_cents::text, ',' ORDER BY community_id, property_id, tenure_id), '')) INTO b_cur FROM v_current_owner_balance;
  SELECT md5(coalesce(string_agg(community_id::text || '|' || coalesce(tenure_id::text, '') || '|' || coalesce(property_id::text, '') || '|' || coalesce(vantaca_account_id, '') || '|' || balance_cents::text, ',' ORDER BY community_id, tenure_id, property_id, vantaca_account_id), '')) INTO b_former FROM v_former_owner_ledger_balances;
  SELECT md5(coalesce(string_agg(id::text || '|' || coalesce(vantaca_account_id, '') || '|' || coalesce(trusted_account_number, ''), ',' ORDER BY id), '')) INTO b_props FROM properties;
  SELECT md5(coalesce(string_agg(id::text || '|' || community_id::text || '|' || coalesce(property_id::text, '') || '|' || kind || '|' || coalesce(end_date::text, '') || '|' || coalesce(vantaca_account_id, '') || '|' || origin || '|' || coalesce(created_by_proposal_id::text, ''), ',' ORDER BY id), '')) INTO b_ten FROM ownership_tenures;
  SELECT md5(coalesce(string_agg(id::text || '|' || coalesce(property_id::text, '') || '|' || coalesce(contact_id::text, '') || '|' || coalesce(end_date::text, '') || '|' || coalesce(tenure_id::text, '') || '|' || coalesce(is_primary::text, '') || '|' || coalesce(source, ''), ',' ORDER BY id), '')) INTO b_own FROM property_ownerships;
  SELECT md5(coalesce(string_agg(t.id::text || '|' || coalesce(t.start_date::text, '') || '|' || coalesce(t.start_date_basis, ''), ',' ORDER BY t.id), '')) INTO b_ten_other
    FROM ownership_tenures t WHERE NOT EXISTS (SELECT 1 FROM _m553 d WHERE d.tenure_id = t.id);
  SELECT md5(coalesce(string_agg(o.id::text || '|' || coalesce(o.start_date::text, '') || '|' || o.updated_at::text, ',' ORDER BY o.id), '')) INTO b_own_other
    FROM property_ownerships o WHERE NOT EXISTS (SELECT 1 FROM _m553 d WHERE d.tenure_id = o.tenure_id AND o.end_date IS NULL);

  -- The audit record first (the evidence), then the dates.
  SELECT d.community_id, d.property_id, d.tenure_id,
         (SELECT array_agg(o.id ORDER BY o.id) FROM property_ownerships o WHERE o.tenure_id = d.tenure_id AND o.end_date IS NULL),
         d.prior_start, d.new_start,
         CASE WHEN d.new_start IS NULL THEN 'cleared_unknown' ELSE 'county_deed_date' END, d.reason,
         jsonb_build_object(
           'county', 'Fort Bend Central Appraisal District (FBCAD)',
           'checked', jsonb_build_array(
             jsonb_build_object('roll', 'certified_2026', 'file', 'FBCAD2026CertifiedGISData-ParcelsShapefiles.zip > Shapefiles/CamaSummary/CamaSummary.dbf',
               'source_url', 'https://www.fbcad.org/wp-content/uploads/2026/07/FBCAD2026CertifiedGISData-ParcelsShapefiles.zip', 'published', '2026-07-09',
               'zip_sha256', '9210e52fe6b1ad3d65170fbe297b09da401c98820baf05a626c3031704d35873',
               'dbf_sha256', '4200b948e8ce2fff3981a8e489ed2d2422d91a2c73286b376e1a9650caccfdd7', 'retrieved_at', '2026-10-31'),
             jsonb_build_object('roll', 'preliminary_2026', 'file', 'FBCAD 2026 Preliminary GIS Data > CamaSummary.dbf', 'published', '2026-04-15',
               'dbf_sha256', '9ee272edbc6ccc489206e5ed53a7f95f68a06f9a3cf2f924a2b496f9011d6c05', 'retrieved_at', '2026-06-11')),
           'matched_by', 'situs address + zip, exactly one parcel; county owner name agrees with the trustEd owner',
           'roll', d.roll, 'cad_reference', d.cad_reference, 'property_number', d.property_number, 'instrument', d.instrument, 'deed_date', d.deed_date,
           'date_type', CASE WHEN d.new_start IS NULL THEN NULL ELSE 'county_deed_date' END,
           'date_note', CASE WHEN d.new_start IS NULL THEN 'no reliable county date: start unknown (before trustEd history)'
                             ELSE 'deed date from the county appraisal roll: recording evidence, not a confirmed closing date' END,
           'prior_start_was', 'roster load date')
    FROM _m553 d;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n <> 2332 THEN RAISE EXCEPTION 'guard: % correction records, expected 2332', n; END IF;

  -- The tenure key is immutable by design (456); this one-time correction lifts that guard for this
  -- statement only and restores it in the same transaction.
  ALTER TABLE ownership_tenures DISABLE TRIGGER trg_ownership_tenures_guard;
  UPDATE ownership_tenures t SET start_date = d.new_start, start_date_basis = CASE WHEN d.new_start IS NULL THEN 'unknown' ELSE 'county_deed' END
    FROM _m553 d WHERE t.id = d.tenure_id AND t.start_date = d.prior_start AND t.end_date IS NULL AND t.origin = 'backfill_current';
  GET DIAGNOSTICS n = ROW_COUNT;
  ALTER TABLE ownership_tenures ENABLE TRIGGER trg_ownership_tenures_guard;
  IF n <> 2332 THEN RAISE EXCEPTION 'guard: % ownership periods updated, expected 2332', n; END IF;

  UPDATE property_ownerships o SET start_date = d.new_start, updated_at = now()
    FROM _m553 d WHERE o.tenure_id = d.tenure_id AND o.end_date IS NULL AND o.start_date = d.prior_start;
  GET DIAGNOSTICS v = ROW_COUNT;
  SELECT count(*) INTO n FROM ownership_start_date_corrections c, unnest(c.ownership_ids) x;
  IF v <> n THEN RAISE EXCEPTION 'guard: % ownerships updated, % recorded', v, n; END IF;

  -- ---------------------------- guards -------------------------------------
  SELECT count(*) INTO n FROM pg_trigger WHERE tgname = 'trg_ownership_tenures_guard' AND tgenabled = 'O';
  IF n <> 1 THEN RAISE EXCEPTION 'guard: the tenure guard trigger is not enabled'; END IF;
  SELECT md5(coalesce(string_agg(community_id::text || '|' || coalesce(vantaca_account_id, '') || '|' || coalesce(property_id::text, '') || '|' || coalesce(contact_id::text, '') || '|' || balance_cents::text, ',' ORDER BY community_id, vantaca_account_id, property_id, contact_id), '')) INTO h FROM v_homeowner_current_balance;
  IF h <> b_bal THEN RAISE EXCEPTION 'guard: homeowner balances changed'; END IF;
  SELECT md5(coalesce(string_agg(community_id::text || '|' || property_id::text || '|' || tenure_id::text || '|' || balance_cents::text, ',' ORDER BY community_id, property_id, tenure_id), '')) INTO h FROM v_current_owner_balance;
  IF h <> b_cur THEN RAISE EXCEPTION 'guard: current-owner balances changed'; END IF;
  SELECT md5(coalesce(string_agg(community_id::text || '|' || coalesce(tenure_id::text, '') || '|' || coalesce(property_id::text, '') || '|' || coalesce(vantaca_account_id, '') || '|' || balance_cents::text, ',' ORDER BY community_id, tenure_id, property_id, vantaca_account_id), '')) INTO h FROM v_former_owner_ledger_balances;
  IF h <> b_former THEN RAISE EXCEPTION 'guard: former-owner balances changed'; END IF;
  SELECT md5(coalesce(string_agg(id::text || '|' || coalesce(vantaca_account_id, '') || '|' || coalesce(trusted_account_number, ''), ',' ORDER BY id), '')) INTO h FROM properties;
  IF h <> b_props THEN RAISE EXCEPTION 'guard: a property account number changed'; END IF;
  SELECT md5(coalesce(string_agg(id::text || '|' || community_id::text || '|' || coalesce(property_id::text, '') || '|' || kind || '|' || coalesce(end_date::text, '') || '|' || coalesce(vantaca_account_id, '') || '|' || origin || '|' || coalesce(created_by_proposal_id::text, ''), ',' ORDER BY id), '')) INTO h FROM ownership_tenures;
  IF h <> b_ten THEN RAISE EXCEPTION 'guard: a tenure''s owner, lot, account or end date changed'; END IF;
  SELECT md5(coalesce(string_agg(id::text || '|' || coalesce(property_id::text, '') || '|' || coalesce(contact_id::text, '') || '|' || coalesce(end_date::text, '') || '|' || coalesce(tenure_id::text, '') || '|' || coalesce(is_primary::text, '') || '|' || coalesce(source, ''), ',' ORDER BY id), '')) INTO h FROM property_ownerships;
  IF h <> b_own THEN RAISE EXCEPTION 'guard: an ownership''s owner, lot, tenure or end date changed'; END IF;
  SELECT md5(coalesce(string_agg(t.id::text || '|' || coalesce(t.start_date::text, '') || '|' || coalesce(t.start_date_basis, ''), ',' ORDER BY t.id), '')) INTO h
    FROM ownership_tenures t WHERE NOT EXISTS (SELECT 1 FROM ownership_start_date_corrections c WHERE c.tenure_id = t.id);
  IF h <> b_ten_other THEN RAISE EXCEPTION 'guard: a start date outside the list changed'; END IF;
  SELECT md5(coalesce(string_agg(o.id::text || '|' || coalesce(o.start_date::text, '') || '|' || o.updated_at::text, ',' ORDER BY o.id), '')) INTO h
    FROM property_ownerships o WHERE NOT EXISTS (SELECT 1 FROM ownership_start_date_corrections c WHERE c.tenure_id = o.tenure_id AND o.end_date IS NULL);
  IF h <> b_own_other THEN RAISE EXCEPTION 'guard: an ownership outside the list changed'; END IF;
  SELECT count(*) INTO n FROM ownership_tenures t JOIN ownership_start_date_corrections c ON c.tenure_id = t.id
   WHERE t.start_date IS DISTINCT FROM c.corrected_start_date
      OR t.start_date_basis IS DISTINCT FROM CASE WHEN c.corrected_start_date IS NULL THEN 'unknown' ELSE 'county_deed' END;
  IF n <> 0 THEN RAISE EXCEPTION 'guard: % periods do not match their correction record', n; END IF;
  SELECT count(*) INTO n FROM property_ownerships o JOIN ownership_start_date_corrections c ON c.tenure_id = o.tenure_id
   WHERE o.end_date IS NULL AND o.start_date IS DISTINCT FROM c.corrected_start_date;
  IF n <> 0 THEN RAISE EXCEPTION 'guard: % open ownerships do not match their period', n; END IF;
  -- The pending Waterview transfer (0f146aca, settlement 2026-05-04) is no longer blocked by a load date,
  -- and the seller's ledger is untouched (its -56.37 credit stays with the seller account).
  SELECT count(*) INTO n FROM ownership_change_proposals pr
    JOIN ownership_tenures t ON t.property_id = pr.property_id AND t.kind = 'owner' AND t.end_date IS NULL
   WHERE pr.id = '0f146aca-ec7f-4dd7-ad09-81b7b8459e4e' AND pr.status = 'pending'
     AND (t.start_date IS NULL OR t.start_date < pr.effective_start_date)
     AND NOT EXISTS (SELECT 1 FROM property_ownerships o WHERE o.property_id = pr.property_id AND o.end_date IS NULL AND o.start_date > pr.effective_start_date - 1);
  IF n <> 1 THEN RAISE EXCEPTION 'guard: the pending Waterview transfer would still be refused'; END IF;

  RAISE NOTICE 'mig 553 OK: % periods corrected (% county deed dates, % cleared to unknown)', todo,
    (SELECT count(*) FROM ownership_start_date_corrections WHERE action = 'county_deed_date'),
    (SELECT count(*) FROM ownership_start_date_corrections WHERE action = 'cleared_unknown');
  --@@END@@
END
$m553$;

COMMIT;
